"""Verify the flagship model: provable but not provably provable."""
from __future__ import annotations
from typing import Dict, FrozenSet, Set, Tuple


def box(worlds: Set[int], R: Set[Tuple[int, int]], P: FrozenSet[int]) -> FrozenSet[int]:
    """Necessity: w in box P iff every one-step successor of w lies in P."""
    return frozenset(
        w for w in worlds
        if {v for (a, v) in R if a == w} <= set(P)
    )


def main() -> None:
    worlds: Set[int] = {0, 1, 2}
    R: Set[Tuple[int, int]] = {(2, 1), (1, 0)}   # non-transitive chain 2->1->0
    P: FrozenSet[int] = frozenset({1})
    boxP = box(worlds, R, P)
    boxboxP = box(worlds, R, boxP)
    print("box P     =", sorted(boxP))
    print("box box P =", sorted(boxboxP))
    print("2 in box P      :", 2 in boxP)        # True: P is provable at 2
    print("2 in box box P  :", 2 in boxboxP)     # False: not provably provable
    assert 2 in boxP and 2 not in boxboxP
    print("=> (box P and not box box P) is inhabited at world 2.")


if __name__ == "__main__":
    main()

"""Show that transitive frames validate axiom 4 (box P subset box box P),
destroying the 'provable but not provably provable' witness."""
from __future__ import annotations
from itertools import product
from typing import FrozenSet, List, Set, Tuple


def box(worlds: Set[int], R: Set[Tuple[int, int]], P: FrozenSet[int]) -> FrozenSet[int]:
    return frozenset(w for w in worlds if {v for (a, v) in R if a == w} <= set(P))


def all_props(worlds: Set[int]) -> List[FrozenSet[int]]:
    ws = sorted(worlds)
    return [frozenset(w for w, b in zip(ws, bits) if b)
            for bits in product([False, True], repeat=len(ws))]


def is_transitive(R: Set[Tuple[int, int]]) -> bool:
    return all((a, c) in R for (a, b) in R for (b2, c) in R if b == b2)


def main() -> None:
    worlds: Set[int] = {0, 1, 2}
    R: Set[Tuple[int, int]] = {(2, 1), (1, 0), (2, 0)}  # transitive closure
    print("transitive:", is_transitive(R))
    holds = all(set(box(worlds, R, P)) <= set(box(worlds, R, box(worlds, R, P)))
                for P in all_props(worlds))
    print("box P subset box box P for ALL P:", holds)
    assert holds
    P = frozenset({1})
    print("with P={1}: 2 in box box P now:", 2 in box(worlds, R, box(worlds, R, P)))
    print("=> Transitivity forces axiom 4 and kills the witness.")


if __name__ == "__main__":
    main()

"""Check Loeb's law box(box P -> P) -> box P on a converse-well-founded
(strict-order) transitive frame, and confirm it can fail otherwise."""
from __future__ import annotations
from itertools import product
from typing import FrozenSet, List, Set, Tuple

World = int
Rel = Set[Tuple[World, World]]


def box(worlds: Set[World], R: Rel, P: FrozenSet[World]) -> FrozenSet[World]:
    return frozenset(w for w in worlds if {v for (a, v) in R if a == w} <= set(P))


def implies(worlds: Set[World], A: FrozenSet[World], B: FrozenSet[World]) -> FrozenSet[World]:
    return frozenset((worlds - set(A)) | set(B))


def all_props(worlds: Set[World]) -> List[FrozenSet[World]]:
    ws = sorted(worlds)
    return [frozenset(w for w, b in zip(ws, bits) if b)
            for bits in product([False, True], repeat=len(ws))]


def loeb_holds(worlds: Set[World], R: Rel) -> bool:
    for P in all_props(worlds):
        premise = box(worlds, R, implies(worlds, box(worlds, R, P), P))
        if not (set(premise) <= set(box(worlds, R, P))):
            return False
    return True


def main() -> None:
    worlds: Set[World] = {0, 1, 2, 3}
    gl: Rel = {(a, b) for a in worlds for b in worlds if a > b}  # strict order
    print("GL frame (strict order) satisfies Loeb:", loeb_holds(worlds, gl))
    assert loeb_holds(worlds, gl)
    reflexive: Rel = gl | {(a, a) for a in worlds}  # not converse-well-founded
    print("reflexive frame satisfies Loeb:", loeb_holds(worlds, reflexive))
    print("=> Loeb's law is the well-founded fixed-point principle.")


if __name__ == "__main__":
    main()

