"""Bar chart: fraction of propositions satisfying axiom 4 (box P subset box box P)
as a frame moves from non-transitive to its transitive closure."""
from itertools import product
import matplotlib.pyplot as plt


def box(worlds, R, P):
    return frozenset(w for w in worlds if {v for (a, v) in R if a == w} <= set(P))


def all_props(worlds):
    ws = sorted(worlds)
    return [frozenset(w for w, b in zip(ws, bits) if b)
            for bits in product([False, True], repeat=len(ws))]


def frac_axiom4(worlds, R):
    props = all_props(worlds)
    ok = sum(1 for P in props
             if set(box(worlds, R, P)) <= set(box(worlds, R, box(worlds, R, P))))
    return ok / len(props)


def main() -> None:
    worlds = {0, 1, 2}
    non_trans = {(2, 1), (1, 0)}
    trans = {(2, 1), (1, 0), (2, 0)}
    vals = [frac_axiom4(worlds, non_trans), frac_axiom4(worlds, trans)]
    fig, ax = plt.subplots(figsize=(6, 4))
    ax.bar(["non-transitive\n2->1->0", "transitive closure\n+ 2->0"], vals,
           color=["#ef476f", "#06d6a0"])
    ax.set_ylabel("fraction of propositions with box P subset box box P")
    ax.set_ylim(0, 1.05)
    for i, v in enumerate(vals):
        ax.text(i, v + 0.02, f"{v:.2f}", ha="center")
    ax.set_title("Transitivity forces axiom 4 for every proposition")
    plt.tight_layout(); plt.savefig("axiom4.png", dpi=150)
    print("wrote axiom4.png")


if __name__ == "__main__":
    main()

"""Visualize Kleene iteration converging to the least fixpoint
mu X. (A u dia X) = 'eventually reaches A' on the line 0->1->2->3."""
import matplotlib.pyplot as plt


def dia(worlds, R, P):
    return frozenset(w for w in worlds if {v for (a, v) in R if a == w} & set(P))


def main() -> None:
    worlds = {0, 1, 2, 3}
    R = {(0, 1), (1, 2), (2, 3)}
    A = frozenset({3})
    stages = []
    cur = frozenset()
    while True:
        stages.append(sorted(cur))
        nxt = frozenset(set(A) | set(dia(worlds, R, cur)))
        if nxt == cur:
            break
        cur = nxt
    fig, ax = plt.subplots(figsize=(7, 4))
    for i, s in enumerate(stages):
        for w in sorted(worlds):
            ax.scatter([i], [w], s=300,
                       c="#118ab2" if w in s else "#e0e0e0",
                       edgecolors="black", zorder=3)
    ax.set_xlabel("iteration"); ax.set_ylabel("world")
    ax.set_yticks(sorted(worlds))
    ax.set_title("mu X. (A u dia X): least fixpoint reached by iteration from empty set")
    plt.tight_layout(); plt.savefig("fixpoint.png", dpi=150)
    print("wrote fixpoint.png; final =", stages[-1])


if __name__ == "__main__":
    main()
